     if(!pool.length||guCount()>=guCap()){toast('Kein passendes Rezept oder Apertur voll','#ff5d73');return}
     const k=pick(pool);P.guState[k]={hunger:100};applyGuPassive(k);addDao(GUDEX[k].path,8);
     toast(`${GUDEX[k].ic} ${GUDEX[k].n} erlernt`,RANKGU_C[GUDEX[k].rank])}
